
.shell {
  width: min(100%, 72rem);
  margin: 0 auto;
  padding: 0.8rem;
  display: grid;
  gap: 0.8rem;
  container-type: inline-size;
}

.top-banner,
.panel {
  border: 1px solid var(--gob-border);
  border-radius: 1.5rem;
  background:
    radial-gradient(circle at top left, rgba(222, 191, 133, 0.08), transparent 24%),
    linear-gradient(180deg, var(--gob-panel), rgba(18, 12, 9, 0.98));
  box-shadow: 0 18px 42px rgba(0, 0, 0, 0.26);
}

.top-banner {
  display: flex;
  justify-content: space-between;
  gap: 1rem;
  padding: 1rem 1.05rem;
}

.banner-copy h1,
.panel-head h2,
.modal-head h2 {
  margin: 0.35rem 0 0;
  color: var(--gob-accent-strong);
  font-size: clamp(1.25rem, 4cqi, 2rem);
  line-height: 1.08;
}

.eyebrow {
  color: rgba(226, 195, 136, 0.92);
  font-size: 0.7rem;
  letter-spacing: 0.18em;
  text-transform: uppercase;
}

.banner-copy p,
.lead-copy,
.ink-card p,
.detail-note,
blockquote {
  color: var(--gob-subtle);
  line-height: 1.62;
}

.compact {
  margin-top: 0.3rem;
}

.action-group {
  display: flex;
  gap: 0.55rem;
  align-items: start;
}

.accent-button,
.ghost-button,
.tabs button,
.unit-pill,
.unit-row,
.close-button {
  border: 0;
  cursor: pointer;
  font: inherit;
}

.accent-button,
.ghost-button,
.tabs button {
  border-radius: 999px;
  padding: 0.68rem 0.98rem;
}

.accent-button {
  color: #24140d;
  background: linear-gradient(180deg, #f2d69f, #d6a762);
  box-shadow: 0 10px 22px rgba(175, 124, 57, 0.26);
}

.ghost-button,
.tabs button,
.unit-pill,
.unit-row,
.close-button {
  background: rgba(255, 255, 255, 0.055);
  color: var(--gob-text);
}

.ghost-button.small {
  padding: 0.52rem 0.82rem;
}

.chip-row,
.body-tags,
.meta-row {
  display: flex;
  gap: 0.45rem;
  flex-wrap: wrap;
}

.chip,
.meta-row span,
.body-tags span {
  border-radius: 999px;
  padding: 0.42rem 0.7rem;
  background: rgba(112, 136, 70, 0.16);
  color: #e8f1c9;
  font-size: 0.78rem;
}

.chip.alt,
.meta-row span,
.body-tags span {
  background: rgba(218, 190, 140, 0.1);
  color: var(--gob-subtle);
}

.board-grid {
  display: grid;
  grid-template-columns: repeat(12, minmax(0, 1fr));
  gap: 0.8rem;
}

.span-7 {
  grid-column: span 7;
}

.span-5 {
  grid-column: span 5;
}

.span-4 {
  grid-column: span 4;
}

.panel {
  padding: 0.95rem;
}

.panel-head,
.sub-head,
.chronicle-footer {
  display: flex;
  justify-content: space-between;
  gap: 0.75rem;
  align-items: start;
}

.stamp-group {
  display: grid;
  gap: 0.35rem;
  justify-items: end;
  color: var(--gob-subtle);
  font-size: 0.76rem;
}

.panel-tag,
.sub-head span {
  color: rgba(226, 195, 136, 0.88);
  font-size: 0.73rem;
  letter-spacing: 0.1em;
  text-transform: uppercase;
}

.dual-cards,
.panel-split,
.tab-grid,
.modal-grid {
  display: grid;
  gap: 0.75rem;
}

.dual-cards,
.panel-split,
.tab-grid {
  grid-template-columns: repeat(2, minmax(0, 1fr));
}

.ink-card,
.meter-card,
.stat-box,
.chronicle-card,
.chronicle-empty {
  border-radius: 1.1rem;
  border: 1px solid rgba(222, 191, 133, 0.12);
  background:
    linear-gradient(180deg, rgba(48, 32, 22, 0.92), rgba(16, 10, 8, 0.95)),
    radial-gradient(circle at top right, rgba(232, 205, 156, 0.06), transparent 30%);
  padding: 0.8rem;
}

.ink-card.accent {
  background:
    linear-gradient(180deg, rgba(60, 30, 24, 0.94), rgba(22, 11, 9, 0.97)),
    radial-gradient(circle at top right, rgba(177, 92, 77, 0.16), transparent 34%);
}

.full {
  margin-top: 0.75rem;
}

.scroll-card {
  border-radius: 1.1rem;
  border: 1px solid rgba(222, 191, 133, 0.12);
  background: rgba(14, 10, 8, 0.36);
  padding: 0.8rem;
}

.event-list,
.unit-stack,
.chronicle-body,
.detail-stack {
  display: grid;
  gap: 0.55rem;
}

.event-list {
  margin: 0.75rem 0 0;
  padding-left: 1rem;
  max-block-size: 11.5rem;
  overflow: auto;
}

.event-list.compact {
  max-block-size: 17rem;
}

.event-list li {
  color: var(--gob-subtle);
  line-height: 1.52;
}

.meter-grid {
  display: grid;
  grid-template-columns: repeat(2, minmax(0, 1fr));
  gap: 0.65rem;
}

.compact-meters {
  margin-bottom: 0.75rem;
}

.metric-top {
  display: flex;
  justify-content: space-between;
  gap: 0.6rem;
  margin-bottom: 0.45rem;
}

.metric-top span {
  color: var(--gob-subtle);
  font-size: 0.77rem;
}

.metric-top strong {
  color: var(--gob-accent-strong);
  font-size: 1rem;
}

.metric-track {
  height: 0.45rem;
  border-radius: 999px;
  background: rgba(255, 255, 255, 0.08);
  overflow: hidden;
}

.metric-fill {
  height: 100%;
  border-radius: inherit;
  background: linear-gradient(90deg, #d8b170, #f5e0b5);
}

.tone-gold {
  background: linear-gradient(90deg, #b98c4f, #f3d59c);
}

.tone-green {
  background: linear-gradient(90deg, #5f7f48, #bdd29a);
}

.tone-red {
  background: linear-gradient(90deg, #8b4036, #d59a84);
}

blockquote {
  margin: 0.8rem 0 0;
  padding-left: 0.8rem;
  border-left: 3px solid rgba(214, 184, 125, 0.3);
}

.mini-list {
  display: grid;
  gap: 0.65rem;
  margin-top: 0.75rem;
}

.dense span {
  padding: 0.34rem 0.58rem;
  font-size: 0.75rem;
}

.stat-boxes {
  display: grid;
  grid-template-columns: repeat(2, minmax(0, 1fr));
  gap: 0.65rem;
}

.stat-box {
  display: grid;
  gap: 0.25rem;
  justify-items: start;
}

.stat-box span {
  color: var(--gob-subtle);
  font-size: 0.76rem;
}

.stat-box strong {
  color: var(--gob-accent-strong);
  font-size: 1.7rem;
}

.stat-box.gob {
  background:
    linear-gradient(180deg, rgba(44, 56, 27, 0.96), rgba(19, 14, 9, 0.95)),
    radial-gradient(circle at top right, rgba(124, 154, 86, 0.16), transparent 34%);
}

.tabs {
  display: grid;
  grid-template-columns: repeat(4, minmax(0, 1fr));
  gap: 0.5rem;
  margin-bottom: 0.8rem;
}

.tabs .active {
  color: #24140d;
  background: linear-gradient(180deg, #f2d69f, #d6a762);
}

.full-height {
  min-height: 0;
}

.unit-row {
  width: 100%;
  display: flex;
  justify-content: space-between;
  gap: 0.75rem;
  align-items: center;
  border-radius: 1rem;
  padding: 0.72rem 0.84rem;
  text-align: left;
}

.unit-row.gob,
.unit-pill.gob {
  background: rgba(124, 154, 86, 0.14);
}

.unit-row p {
  margin: 0.22rem 0 0;
}

.roster-lists {
  display: grid;
  grid-template-columns: repeat(2, minmax(0, 1fr));
  gap: 0.75rem;
}

.roster-label {
  display: block;
  margin-bottom: 0.55rem;
  color: var(--gob-subtle);
  font-size: 0.77rem;
}

.unit-pill {
  width: 100%;
  border-radius: 1rem;
  padding: 0.65rem 0.8rem;
  text-align: left;
  margin-bottom: 0.45rem;
}

.chronicle-body {
  max-block-size: 24rem;
  overflow: auto;
}

.chronicle-card p {
  margin: 0.6rem 0;
}

.chronicle-footer {
  margin-top: 0.65rem;
  color: var(--gob-subtle);
  font-size: 0.77rem;
}

.label {
  color: rgba(226, 195, 136, 0.92);
}

.modal-backdrop {
  position: fixed;
  inset: 0;
  display: flex;
  align-items: center;
  justify-content: center;
  padding: 1rem;
  background: rgba(7, 5, 4, 0.72);
  backdrop-filter: blur(10px);
  z-index: 50;
}

.modal-card {
  position: relative;
  width: min(62rem, 100%);
  max-height: 92vh;
  overflow: auto;
  border-radius: 1.7rem;
  border: 1px solid var(--gob-border-strong);
  background:
    radial-gradient(circle at top right, rgba(217, 176, 107, 0.12), transparent 24%),
    linear-gradient(180deg, rgba(43, 28, 18, 0.98), rgba(14, 10, 8, 0.99));
  padding: 1.15rem;
  box-shadow: 0 28px 68px rgba(0, 0, 0, 0.42);
}

.builder-modal {
  width: min(74rem, 100%);
}

.close-button {
  position: sticky;
  top: 0;
  margin-left: auto;
  display: block;
  width: 2.15rem;
  height: 2.15rem;
  border-radius: 999px;
}

.modal-head {
  display: grid;
  gap: 0.65rem;
  margin-bottom: 0.9rem;
}

.modal-grid {
  grid-template-columns: repeat(2, minmax(0, 1fr));
  margin-bottom: 0.75rem;
}

.modal-meters {
  margin-bottom: 0.75rem;
}

@container (max-width: 1040px) {
  .span-7,
  .span-5,
  .span-4 {
    grid-column: span 12;
  }

  .top-banner,
  .panel-split,
  .dual-cards,
  .tab-grid,
  .modal-grid {
    grid-template-columns: 1fr;
  }
}

@container (max-width: 820px) {
  .action-group,
  .tabs,
  .meter-grid,
  .roster-lists,
  .stat-boxes {
    grid-template-columns: 1fr;
  }

  .top-banner,
  .action-group {
    flex-direction: column;
  }

  .action-group {
    align-items: stretch;
  }

  .tabs {
    display: grid;
  }
}

@container (max-width: 560px) {
  .shell {
    padding: 0.55rem;
  }

  .panel,
  .top-banner,
  .modal-card {
    padding: 0.85rem;
    border-radius: 1.2rem;
  }

  .chip-row,
  .meta-row,
  .body-tags {
    gap: 0.35rem;
  }
}
