
.builder-shell {
  --ink: #2a160d;
  --paper: #d7bf8f;
  --paper-soft: rgba(216, 198, 155, 0.72);
  --paper-line: rgba(108, 72, 38, 0.26);
  --deep-shadow: 0 22px 50px rgba(20, 10, 6, 0.32);
  container-type: inline-size;
  display: grid;
  gap: 0.95rem;
  color: #f6ead3;
  font-family: 'Palatino Linotype', 'Book Antiqua', 'STSong', serif;
}

.hero,
.section-card,
.step-strip {
  position: relative;
  border: 1px solid rgba(184, 150, 100, 0.28);
  border-radius: 1.6rem;
  overflow: hidden;
  background:
    radial-gradient(circle at top left, rgba(241, 213, 160, 0.12), transparent 28%),
    radial-gradient(circle at bottom right, rgba(74, 102, 58, 0.12), transparent 30%),
    linear-gradient(180deg, rgba(55, 34, 22, 0.96), rgba(24, 15, 11, 0.97));
  box-shadow: var(--deep-shadow);
}

.hero::before,
.section-card::before,
.step-strip::before {
  content: '';
  position: absolute;
  inset: 0;
  background:
    linear-gradient(135deg, rgba(255, 255, 255, 0.035), transparent 24%),
    repeating-linear-gradient(135deg, rgba(255, 255, 255, 0.018) 0 2px, transparent 2px 18px);
  pointer-events: none;
}

.hero,
.section-card,
.step-strip,
.stack-sections,
.footer {
  position: relative;
  z-index: 1;
}

.hero {
  display: grid;
  grid-template-columns: minmax(0, 1.2fr) minmax(16rem, 0.8fr);
  gap: 1rem;
  padding: 1.1rem 1.15rem;
}

.hero-copy h2,
.section-title h3 {
  margin: 0.3rem 0 0;
  color: #f5dfb0;
  font-size: clamp(1.2rem, 3.4cqi, 1.95rem);
  line-height: 1.12;
}

.hero-copy p,
.section-title span,
.hero-summary p,
.fixed-sex {
  margin: 0;
  color: rgba(243, 233, 208, 0.82);
  line-height: 1.65;
  font-size: 0.88rem;
}

.hero-summary {
  display: grid;
  align-content: start;
  gap: 0.35rem;
  padding: 0.9rem 1rem;
  border-radius: 1.2rem;
  border: 1px solid rgba(214, 184, 125, 0.16);
  background:
    radial-gradient(circle at top, rgba(108, 86, 46, 0.18), transparent 55%),
    linear-gradient(180deg, rgba(29, 19, 13, 0.86), rgba(16, 10, 8, 0.92));
}

.summary-label,
.eyebrow,
.field span {
  display: inline-block;
  color: rgba(221, 193, 136, 0.92);
  font-size: 0.7rem;
  letter-spacing: 0.16em;
  text-transform: uppercase;
}

.hero-summary strong {
  font-size: clamp(1.3rem, 4.2cqi, 2rem);
  color: #f8e7c2;
}

.step-strip {
  display: grid;
  grid-template-columns: repeat(4, minmax(0, 1fr));
  gap: 0.7rem;
  padding: 0.7rem;
}

.step-chip,
.mini-button,
.ghost-button,
.primary-button,
.text-button {
  border: 0;
  cursor: pointer;
  font: inherit;
}

.step-chip {
  min-width: 0;
  display: grid;
  gap: 0.2rem;
  justify-items: start;
  padding: 0.8rem 0.9rem;
  border-radius: 1rem;
  border: 1px solid rgba(216, 188, 136, 0.14);
  background: rgba(15, 10, 8, 0.28);
  color: rgba(247, 237, 214, 0.74);
  text-align: left;
  transition: transform 0.16s ease, border-color 0.16s ease, background 0.16s ease;
}

.step-chip span {
  color: rgba(237, 199, 126, 0.78);
  font-size: 0.75rem;
}

.step-chip strong {
  font-size: 0.92rem;
}

.step-chip:hover,
.step-chip.active {
  transform: translateY(-1px);
  border-color: rgba(233, 205, 152, 0.35);
  background: linear-gradient(180deg, rgba(105, 73, 38, 0.26), rgba(32, 19, 12, 0.78));
  color: #fff2d7;
}

.section-card {
  padding: 1rem;
}

.stack-sections {
  display: grid;
  gap: 0.95rem;
}

.section-title {
  display: flex;
  flex-direction: column;
  gap: 0.25rem;
  margin-bottom: 0.85rem;
}

.inline-actions {
  flex-direction: row;
  justify-content: space-between;
  align-items: start;
  gap: 0.8rem;
}

.field-grid,
.card-grid {
  display: grid;
  grid-template-columns: repeat(2, minmax(0, 1fr));
  gap: 0.75rem;
}

.field-grid.compact {
  grid-template-columns: repeat(2, minmax(0, 1fr));
}

.field {
  display: flex;
  flex-direction: column;
  gap: 0.38rem;
}

.wide {
  grid-column: 1 / -1;
}

input,
select,
textarea {
  width: 100%;
  border-radius: 1rem;
  border: 1px solid rgba(216, 188, 136, 0.18);
  background:
    linear-gradient(180deg, rgba(19, 12, 9, 0.88), rgba(12, 8, 6, 0.92)),
    linear-gradient(180deg, rgba(255, 255, 255, 0.03), transparent);
  color: #fff7e6;
  padding: 0.78rem 0.86rem;
  outline: none;
  transition: border-color 0.18s ease, box-shadow 0.18s ease, transform 0.18s ease;
  box-sizing: border-box;
  font-size: 0.95rem;
}

input:focus,
select:focus,
textarea:focus {
  border-color: rgba(238, 201, 132, 0.52);
  box-shadow: 0 0 0 3px rgba(186, 142, 73, 0.16);
  transform: translateY(-1px);
}

textarea {
  resize: vertical;
  min-height: 5.3rem;
  line-height: 1.55;
}

.unit-card {
  border-radius: 1.25rem;
  border: 1px solid rgba(218, 190, 140, 0.14);
  background:
    radial-gradient(circle at top right, rgba(207, 167, 102, 0.08), transparent 32%),
    linear-gradient(180deg, rgba(47, 30, 21, 0.94), rgba(17, 11, 8, 0.96));
  padding: 0.9rem;
}

.goblin-card {
  background:
    radial-gradient(circle at top right, rgba(111, 145, 74, 0.14), transparent 32%),
    linear-gradient(180deg, rgba(36, 47, 24, 0.96), rgba(18, 14, 9, 0.97));
}

.card-head {
  display: flex;
  justify-content: space-between;
  align-items: center;
  gap: 0.75rem;
  margin-bottom: 0.7rem;
  color: #f4e7c4;
}

.detail-box {
  margin-top: 0.75rem;
  border-top: 1px dashed rgba(214, 184, 125, 0.2);
  padding-top: 0.75rem;
}

.detail-box summary {
  cursor: pointer;
  color: rgba(240, 213, 161, 0.88);
  font-size: 0.83rem;
  letter-spacing: 0.08em;
}

.detail-box[open] summary {
  margin-bottom: 0.7rem;
}

.mini-button,
.ghost-button,
.text-button,
.primary-button {
  border-radius: 999px;
  padding: 0.7rem 1rem;
}

.mini-button,
.ghost-button,
.text-button {
  background: rgba(255, 255, 255, 0.055);
  color: #f3e5c7;
}

.mini-button:disabled,
.text-button:disabled {
  opacity: 0.4;
  cursor: not-allowed;
}

.text-button {
  padding: 0.45rem 0.85rem;
}

.primary-button {
  color: #2b190f;
  background:
    linear-gradient(180deg, #f4d79d, #d7ab68),
    linear-gradient(180deg, rgba(255, 255, 255, 0.28), transparent);
  box-shadow: 0 12px 24px rgba(158, 109, 42, 0.26);
}

.error-box {
  border-radius: 1.2rem;
  border: 1px solid rgba(218, 99, 76, 0.44);
  background: rgba(103, 25, 18, 0.42);
  color: #ffd6cb;
  padding: 0.85rem 1rem;
  line-height: 1.6;
}

.footer {
  display: flex;
  justify-content: flex-end;
  gap: 0.65rem;
  flex-wrap: wrap;
}

@container (max-width: 1040px) {
  .hero {
    grid-template-columns: 1fr;
  }
}

@container (max-width: 820px) {
  .step-strip,
  .field-grid,
  .field-grid.compact,
  .card-grid {
    grid-template-columns: 1fr;
  }

  .inline-actions {
    flex-direction: column;
  }
}

@container (max-width: 560px) {
  .section-card,
  .hero {
    padding: 0.9rem;
    border-radius: 1.25rem;
  }

  .footer {
    flex-direction: column-reverse;
  }

  .step-chip {
    padding: 0.7rem 0.75rem;
  }
}
